namespace Lingozi.Library.Items;

/// <summary>Body of <c>POST /api/library/items</c> (README "KnowledgeItemInput" + <c>clientRequestId</c>). Everything is nullable so missing fields become validation errors, not 500s.</summary>
/// <param name="ClientRequestId">Generated by the form each time it opens; makes retries idempotent (BR-LIB-008).</param>
/// <param name="Kind"><c>word</c> or <c>grammar</c> (BR-LIB-002).</param>
/// <param name="Term">"Từ" or "Tên cấu trúc".</param>
/// <param name="Meaning">"Nghĩa" (word, required) or "Ý nghĩa" (grammar, optional).</param>
/// <param name="Formula">"Công thức" (grammar only, required).</param>
/// <param name="PartOfSpeech">"Loại từ" (word only, optional).</param>
/// <param name="Ipa">"Phiên âm" (word only, optional).</param>
/// <param name="Note">"Ghi chú".</param>
/// <param name="Examples">0 to 20 example sentences.</param>
public sealed record KnowledgeItemInput(
    Guid? ClientRequestId,
    string? Kind,
    string? Term,
    string? Meaning,
    string? Formula,
    string? PartOfSpeech,
    string? Ipa,
    string? Note,
    IReadOnlyList<ExampleInput>? Examples,
    // Only for PUT: the RowVersion of the item the client last read, base64 (BR-LIB-007).
    string? Version = null);

/// <param name="Text">English sentence.</param>
/// <param name="Translation">Optional Vietnamese translation.</param>
public sealed record ExampleInput(string? Text, string? Translation);
